def main():
 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated/primaryP1_ritz_primaldual1/summary.json';s=json.loads(src.read_text());c=np.load(REPO/s['output']['path']);par=json.loads((REPO/s['source']['path']).read_text());r=load_ritz(par);V=r['V'];P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);x=c['before_x'];z=x+V@c['coefficients'];dx=z-x;y=c['physical_dual'];eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);ine=~eq;sl=A@z-p['lower'];res=P@z+p['q']+A.T@y;obj=lambda w:float(.5*w@(P@w)+p['q']@w);pr=max(float(np.max(np.maximum(-sl[ine],0))),float(np.max(abs(sl[eq]))));gt=float((P@x+p['q'])@dx);accepted=bool(np.all(np.isfinite(z)) and pr<1e-10 and gt<0 and obj(z)<=obj(x)+1e-4*gt);m=dict(primal_mm=pr,stationarity_N=float(np.max(abs(res))),gauge_N=float(np.max(abs(y[eq]))),RootY_gamma_stationarity_N=float(abs(y[2175])),sign_N=float(np.max(np.maximum(y[ine],0))),complementarity_Nmm=float(np.max(abs(sl[ine]*y[ine]))),reduced_stationarity=float(np.max(abs(V.T@res))),objective_before_Nmm=obj(x),objective_proposal_Nmm=obj(z));qualified=accepted and all(m[k]<1e-8 for k in ['stationarity_N','gauge_N','RootY_gamma_stationarity_N','sign_N','complementarity_Nmm']);N=c['equality_nullspace'];cp=c['equality_particular'];B=A@V;initial=A@x-p['lower'];rs=1/np.maximum(np.max(abs(B),axis=1),1e-15);unit=max(float(np.max(abs(r['g']))),1e-15);mapped=-unit*rs[ine]*c['interior_lambda'];checks=dict(source_hash=sha(REPO/s['source']['path'])==s['source']['SHA256'],output_hash=sha(REPO/s['output']['path'])==s['output']['SHA256'],all_original2208rows=A.shape[0]==2208,physical_H_unchanged=np.max(abs(r['H']-V.T@(P@V)))<1e-7,physical_g_unchanged=np.max(abs(r['g']-V.T@(P@x+p['q'])))<1e-10,equality_particular_all_original=np.max(abs(B[eq]@cp+initial[eq]))<1e-10,equality_nullspace_all_original=np.max(abs((rs[eq,None]*B[eq])@N))<1e-10,original_cone_dual_mapping=np.max(abs(mapped-y[ine]))<1e-10,proposal_reproduced=np.max(abs(z-c['proposed_x']))<1e-12,full_residual_reproduced=np.max(abs(res-c['physical_residual']))<1e-8,acceptance_reproduced=accepted==bool(s['accepted_linear_steps']),saved_state_reproduced=np.max(abs(c['after_x']-(z if accepted else x)))<1e-12,physical_qualification_reproduced=qualified==s['physical_KKT_qualified'],no_nonlinear_update=s['actual_support_updates']==0,zero_physical_regularization=s['physical_regularization']==0);controls=dict(wrong_dual_sign_N=float(np.max(abs(2*A.T@y))),wrong_affine_N=float(np.max(abs(2*p['q']))));checks['negative_sign_control']=controls['wrong_dual_sign_N']>1e-8;checks['negative_affine_control']=controls['wrong_affine_N']>1e-8;ok=all(checks.values());dump(out/'summary.json',dict(status='ACTUAL_P1_PRIMAL_DUAL_ORIGINAL_UNIT_AUDIT_PASS' if ok else 'ACTUAL_P1_PRIMAL_DUAL_ORIGINAL_UNIT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in checks.items()},metrics=m,negative_controls=controls,physical_KKT_qualified=bool(qualified),accepted_linear_steps=int(accepted),actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t,limitations=['Original-unit proposal/equality/dual/acceptance audit, not every interior iteration or nonlinear equilibrium. Full gauge/force rejection remains mandatory even when reduced residuals decrease.']));print(json.dumps(dict(checks=checks,metrics=m),default=bool));raise SystemExit(0 if ok else 2)
